// SPDX-License-Identifier: MIT
// Q0_V — Per-Block Parametric-Curve Quantization: constant lookup tables.
//
// K and V are calibrated SEPARATELY: each side gets its own codebook fitted
// to its own statistics. The kernel selects between them at compile time
// via `template <bool IS_K>`. Five tables per side:
//
//   1. q0_v_curve_table_<side>[256][32]            — 256 calibrated curves (i8,
//                                                    [-127, +127]). 8192 B.
//                                                    Selected by curve_idx (8 bits).
//                                                    Internal layout: 16 buckets
//                                                    × 16 phases.
//   2. q0_v_scale_table_bits_<side>[32]            — 32-entry scale codebook stored
//                                                    as f16 BIT PATTERNS (u16). The
//                                                    stored value is `scale_norm /
//                                                    127`, so the curve's `/127`
//                                                    normalisation is pre-baked into
//                                                    scale.  64 B.
//   3. q0_v_centroid_table_bits_<side>[32][8]      — per-scale centroid codebook,
//                                                    f16 bit patterns (u16) in
//                                                    [-1, +1].  512 B.
//   4. q0_v_peak_curve_indices_<side>[256]         — permutation of 0..255 sorted
//                                                    by curve peak lane (lane of
//                                                    max |curve[lane]|).  256 B.
//                                                    Used by the encoder's peak-
//                                                    bin search.
//   5. q0_v_peak_bin_offsets_<side>[33]            — bin L's curves are at
//                                                    peak_curve_indices[offsets[L]
//                                                    ..offsets[L+1]).  66 B.
//
// Total constant memory: 9 090 B per side, 18 180 B both.
//
// Per-block 2-byte layout (16 bits):
//   byte 0 (lo):  curve_idx
//   byte 1 (hi):  bits[4:0] = scale_idx,  bits[7:5] = centroid_idx
//
// Decode for element e (single FMA, ZERO constant multiplications):
//   curve     = (float)q0_v_curve_table_<side>[curve_idx][e]
//   scale     = __half2float(__ushort_as_half(q0_v_scale_table_bits_<side>[scale_idx]))
//   centroid  = __half2float(__ushort_as_half(q0_v_centroid_table_bits_<side>[scale_idx][centroid_idx]))
//   x[e]      = __fmaf_rn(scale, curve, centroid)
//
// where `scale` already has the curve's `/127` factor folded in. The
// BlockConverter divides by `outer_scale` to recover the original signed value.

#pragma once

#include <stdint.h>
#include <cuda_fp16.h>

