// =============================================================================
// TABLE ACCESSORS  (shared by encoder and decoder)
// =============================================================================
// Both expose the same `const`-method interface:
//   const int8_t* curve(int slot)
//   uint16_t      scale_bits(int i)
//   uint16_t      centroid_bits(int scale_idx, int cent_idx)
//   uint8_t       peak_idx(int i)
//   uint16_t      peak_off(int bin)
//
// `Q0VTablesStatic<IS_K>` is empty — when passed by value its instance
// vanishes under inlining and every method call folds to a direct
// __constant__-memory load. Production hot path is byte-for-byte identical.
//
// `Q0VTablesRuntime` carries device pointers populated by the host and is
// used by the diagnostic / curve-selection round-trip paths to swap the
// codebook at launch time without recompiling the kernel.
namespace q0_v_detail {

template <bool IS_K> struct Q0VTablesStatic;
template <> struct Q0VTablesStatic<true> {
    __device__ __forceinline__ const int8_t* curve(int slot) const { return q0_v_curve_table_k[slot]; }
    __device__ __forceinline__ uint16_t scale_bits(int i)    const { return q0_v_scale_table_bits_k[i]; }
    __device__ __forceinline__ uint16_t centroid_bits(int s, int c) const { return q0_v_centroid_table_bits_k[s][c]; }
    __device__ __forceinline__ uint8_t  peak_idx(int i)      const { return q0_v_peak_curve_indices_k[i]; }
    __device__ __forceinline__ uint16_t peak_off(int bin)    const { return q0_v_peak_bin_offsets_k[bin]; }
};
template <> struct Q0VTablesStatic<false> {
    __device__ __forceinline__ const int8_t* curve(int slot) const { return q0_v_curve_table_v[slot]; }
    __device__ __forceinline__ uint16_t scale_bits(int i)    const { return q0_v_scale_table_bits_v[i]; }
    __device__ __forceinline__ uint16_t centroid_bits(int s, int c) const { return q0_v_centroid_table_bits_v[s][c]; }
    __device__ __forceinline__ uint8_t  peak_idx(int i)      const { return q0_v_peak_curve_indices_v[i]; }
    __device__ __forceinline__ uint16_t peak_off(int bin)    const { return q0_v_peak_bin_offsets_v[bin]; }
};

template <bool IS_K> using Q0VTables = Q0VTablesStatic<IS_K>;

struct Q0VTablesRuntime {
    const int8_t*   curve_table_flat;          // [256 * 32] i8
    const uint16_t* scale_table_bits;           // [32] f16 bits
    const uint16_t* centroid_table_bits_flat;   // [32 * 8] f16 bits
    const uint8_t*  peak_curve_indices;         // [256]
    const uint16_t* peak_bin_offsets;           // [33]

    __device__ __forceinline__ const int8_t* curve(int slot) const {
        return curve_table_flat + (size_t)slot * 32;
    }
    __device__ __forceinline__ uint16_t scale_bits(int i) const { return scale_table_bits[i]; }
    __device__ __forceinline__ uint16_t centroid_bits(int s, int c) const {
        return centroid_table_bits_flat[(size_t)s * 8 + c];
    }
    __device__ __forceinline__ uint8_t  peak_idx(int i)   const { return peak_curve_indices[i]; }
    __device__ __forceinline__ uint16_t peak_off(int bin) const { return peak_bin_offsets[bin]; }
};

}  // namespace q0_v_detail
